  public IReadOnlyList<CatalogProduct> GetAll() => Products;
  public CatalogProduct? GetBySlug(string slug) => Products.FirstOrDefault(product => product.Slug.Equals(slug, StringComparison.OrdinalIgnoreCase));
  public IReadOnlyList<CollectionCard> GetCollections() => Collections;
  public CollectionCard? GetCollection(string slug) => Collections.FirstOrDefault(collection => collection.Slug.Equals(slug, StringComparison.OrdinalIgnoreCase));
  public IReadOnlyList<CatalogProduct> GetCollectionProducts(string slug)
  {
    if (slug.Equals("new-arrivals", StringComparison.OrdinalIgnoreCase)) return Products.Where(product => product.Label == "New").ToList();
    var collection = GetCollection(slug);
    return collection is null ? [] : Products.Where(product => product.Category.Equals(collection.Name, StringComparison.OrdinalIgnoreCase)).ToList();
  }
